var init_self: Instance = .{};

fn globalInit() void {
    const self = &init_self;
    runtime.InstanceManager.get().initDetached(self);
    const m = rt.codePush(self, self);
    defer rt.codePop(m);
    _ = tramp___global_object_depths(self, self, &.{});
    _ = tramp___init_action(self, self, &.{});
    _ = tramp___init_global(self, self, &.{});
}

pub const game: rt.Game = .{
    .object_parents = &object_parents,
    .events = &events,
    .scripts = &script_table,
    .global_init = &globalInit,
};

